import Complex64Array = require( '@stdlib/array/complex64' );
import Complex64 = require( '@stdlib/complex/float32/ctor' );
import cher2 = require( './index' );


// TESTS //

// The function returns a Complex64Array...
{
	const x = new Complex64Array( 10 );
	const y = new Complex64Array( 10 );
	const A = new Complex64Array( 20 );
	const alpha = new Complex64( 2.0, 2.0 );

	cher2( 'row-major', 'lower', 10, alpha, x, 1, y, 1, A, 3 ); // $ExpectType Complex64Array
}

// The compiler throws an error if the function is provided a first argument which is not a string...
{
	const x = new Complex64Array( 10 );
	const y = new Complex64Array( 10 );
	const A = new Complex64Array( 20 );
	const alpha = new Complex64( 2.0, 2.0 );

	cher2( 10, 'lower', 10, alpha, x, 1, y, 1, A, 3 ); // $ExpectError
	cher2( '10', 'lower', 10, alpha, x, 1, y, 1, A, 3 ); // $ExpectError
	cher2( true, 'lower', 10, alpha, x, 1, y, 1, A, 3 ); // $ExpectError
	cher2( false, 'lower', 10, alpha, x, 1, y, 1, A, 3 ); // $ExpectError
	cher2( null, 'lower', 10, alpha, x, 1, y, 1, A, 3 ); // $ExpectError
	cher2( undefined, 'lower', 10, alpha, x, 1, y, 1, A, 3 ); // $ExpectError
	cher2( [], 'lower', 10, alpha, x, 1, y, 1, A, 3 ); // $ExpectError
	cher2( {}, 'lower', 10, alpha, x, 1, y, 1, A, 3 ); // $ExpectError
	cher2( ( x: number ): number => x, 'lower', 10, alpha, x, 1, y, 1, A, 3 ); // $ExpectError
}

