// The compiler throws an error if the function is provided an unsupported number of arguments...
{
	const x = new Complex64Array( 10 );
	const y = new Complex64Array( 10 );
	const A = new Complex64Array( 20 );
	const alpha = new Complex64( 2.0, 2.0 );

	cher2(); // $ExpectError
	cher2( 'row-major' ); // $ExpectError
	cher2( 'row-major', 'lower' ); // $ExpectError
	cher2( 'row-major', 'lower', 10 ); // $ExpectError
	cher2( 'row-major', 'lower', 10, alpha ); // $ExpectError
	cher2( 'row-major', 'lower', 10, alpha, x ); // $ExpectError
	cher2( 'row-major', 'lower', 10, alpha, x, 1 ); // $ExpectError
	cher2( 'row-major', 'lower', 10, alpha, x, 1, y ); // $ExpectError
	cher2( 'row-major', 'lower', 10, alpha, x, 1, y, 1 ); // $ExpectError
	cher2( 'row-major', 'lower', 10, alpha, x, 1, y, 1, A ); // $ExpectError
	cher2( 'row-major', 'lower', 10, alpha, x, 1, y, 1, A, 3, 1 ); // $ExpectError
}

// Attached to main export is an `ndarray` method which returns a Complex64Array...
{
	const x = new Complex64Array( 10 );
	const y = new Complex64Array( 10 );
	const A = new Complex64Array( 20 );
	const alpha = new Complex64( 2.0, 2.0 );

	cher2.ndarray( 'lower', 10, alpha, x, 1, 0, y, 1, 0, A, 3, 1, 0 ); // $ExpectType Complex64Array
}

